typedef long long big_int;
typedef float rational_t;
typedef unsigned char uint8;

class string_buf
{
public:
  big_int *data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;

  inline bool is_equal(const string_buf &buf) const
  {
    if (buf.block_length != block_length) return false;
    for (int i = 0; i < block_length; i++) {
      if (!(buf.data[i] == data[i])) return false;
    }
    return true;
  }
};

class stringx
{
public:
  char *chars;
  string_buf *my_buf;
  stringx &operator=(const stringx &cp);
};

inline bool operator==(const stringx& lhs, const stringx& rhs)
{
  return lhs.my_buf->is_equal(*rhs.my_buf);
}

inline bool operator!=(const stringx& lhs, const stringx& rhs)
{
  return !(lhs == rhs);
}

enum text_widget_justification { JUSTIFY_LEFT };
struct color { float r, g, b, a; };

class typeface_def
{
public:
  void load();
  void unload();
};

typeface_def *typeface_open(const stringx &fname);
void typeface_close(typeface_def *tdefptr);

class text_block_widget
{
public:
  class block_info_t
  {
  public:
    rational_t scale;
    text_widget_justification just;
    stringx typeface;
    uint8 max_lines;
    short line_spacing;
    short max_width;
    stringx break_substring;
    stringx text;
    color col;
  };

  char widget_base[324];
  block_info_t block_info;
  uint8 num_lines_used;
  char pad[3];
  rational_t first_rhw;
  typeface_def *text_font;

  void fill_lines();
  void set_block_info(block_info_t *info_ptr);
};

void text_block_widget::set_block_info( block_info_t *info_ptr )
{
  typeface_def *old_text_font = 0;
  if(text_font && block_info.typeface != info_ptr->typeface)
  {
    old_text_font = text_font;
    text_font = 0;
  }

  block_info = *info_ptr;

  if(!text_font)
  {
    text_font = typeface_open(block_info.typeface);
    text_font->load();
  }

  if(old_text_font)
  {
    old_text_font->unload();
    typeface_close(old_text_font);
    old_text_font = 0;
  }

  fill_lines();
}
